	('bb056356-374a-47fb-a66a-0c86beee48d7', 'cd5e0fe1-2792-490f-9b81-8068c505c53c', '67da2bd3-10e6-4814-8688-215579c102e8', 'Challenge (Part 1)', 'Proyek tantangan pembuatan game dengan MakeCode.', 3001, NULL, NULL, 'Kerjakan Challenge MakeCode. Buat game dengan objectives dan win/lose conditions. Submit game.', '2026-01-29 09:43:55.061761+00', '2026-03-26 12:14:22.347639+00', NULL, NULL, NULL),
