	('19d590de-ae3e-4bca-aeb6-be3293a01173', '6c859fca-cb28-457f-ba4c-ac2c8f66c66f', 'b8103209-8aef-4ba6-a096-6a4d2389c78c', 'Latihan Presentasi', '', 20, 'd75b806f-46f1-45ea-8e71-ce4f4ab0db9f', '2025-10-24 09:15:00+00', NULL, '2026-02-27 10:11:59.750921+00', '2026-03-26 12:15:02.537934+00', NULL, NULL, NULL),
	('afd0b068-2c97-4df8-9760-25be060fe390', '6c859fca-cb28-457f-ba4c-ac2c8f66c66f', 'd36b7263-6a38-479d-a8ed-2f424446fe2d', 'Pitching Day', 'Presentasi Big Project 1', 21, 'ddbe7b93-9164-4bd6-a227-bce069050d65', '2025-10-31 09:15:00+00', 'Siapkan presentasi untuk dipresentasikan di pertemuan berikutnya', '2026-02-27 10:11:59.750921+00', '2026-03-26 12:15:02.582806+00', 'https://docs.google.com/presentation/d/e/2PACX-1vRX42hOv5FMiyiCcqgyEmBHw-98d9xpTxtYNVl6OVgDwdC7lXNpXOYKnCkmTha5VA/embed?start=false&loop=false&delayms=60000', NULL, NULL),
