	('faa872f6-3c3a-4d08-8a69-c55ffcdf412e', 'ba1d7f61-804a-4234-8326-e5d8c369985a', '4ace3c98-0e39-4458-b6eb-3e0781414843', 'Pembuatan Poster Project', '', 12001, '39ce1f63-d645-4d8c-9181-0afdfa5b0980', '2024-09-21 03:30:00+00', NULL, '2026-01-30 04:49:44.639514+00', '2026-03-26 12:14:15.684139+00', NULL, NULL, NULL),
