	('27403ba2-c48a-467c-a120-e2eb89266d16', 'ba1d7f61-804a-4234-8326-e5d8c369985a', 'b26351e4-4795-4f03-888b-9e7dba46f519', 'Latihan Presentasi', '', 13001, 'e220d2fa-98aa-4f12-9428-a3850e8cac1a', '2024-09-28 03:30:00+00', NULL, '2026-01-30 04:49:44.639514+00', '2026-03-26 12:14:15.724601+00', NULL, NULL, NULL),
	('45df32f5-9652-4042-a2e8-ca3511c87a66', '0878baf6-15cf-492e-bed7-093f20eac318', 'f2aaf267-6c5c-414b-8fd8-f8c3162316f8', 'Evaluasi dan Refleksi', 'Evaluasi dan refleksi komprehensif terhadap pengalaman belajar di Blok 4 melalui self evaluation analysing storytelling educational game design promotional communication dan civic entrepreneurship.', 13001, NULL, NULL, 'Create comprehensive self evaluation 1) Creative expression evolution Book Creator comics 2) Educational game design philosophy compare 3 Kodu projects 3) Cultural preservation reflection 4) Promotional thinking 5) Civic entrepreneurship 6) Bebras persistence 7) Holistic portfolio curation 8) Final Blok preparation. Submit thorough evaluation visual portfolio growth evidence goals statement.', '2026-01-29 09:12:25.866926+00', '2026-03-26 12:14:03.678628+00', NULL, NULL, NULL),
