	('34dbc778-676c-4d81-8606-ba7afd58be0a', 'e056165c-365b-481e-8400-83116b75bbde', '8b5320f1-61c5-4650-8ae0-dc8b0e979549', 'Pembuatan Poster Big Project', '', 9001, '03be291c-2fa0-4934-ad3d-1d4d537f1bb3', '2026-04-01 12:30:00+00', NULL, '2026-01-29 09:12:25.497895+00', '2026-03-26 12:14:01.975124+00', NULL, NULL, NULL),
	('f6630833-7f6c-4a84-a0cc-07d681a7335f', '6e8ecdad-f69f-448d-8deb-ad2d6917b622', 'd8fdd2bd-a23b-456f-8c71-c3e8869e2a59', 'Explore GDevelop (Part 1)', 'Pembelajaran game engine GDevelop. Siswa membuat Platform Game.', 6, NULL, NULL, 'Pelajari GDevelop basics behaviors events. Buat platformer level sederhana. Submit game demo.', '2026-03-13 06:51:32.968906+00', '2026-03-26 12:13:50.511609+00', NULL, NULL, NULL),
	('cfc27465-470c-40a2-95c6-17abb117a979', 'a36ca18c-903f-4c79-9464-a8962c0aee77', '5e2e042d-95cc-4fcf-ab0e-3865c4f3d6fa', 'Latihan Presentasi', 'Mendesain logo nama app dan pitch deck. Siapkan presentasi dan demo untuk Pitching Day.', 19001, NULL, NULL, 'Buat branding aplikasi logo dan nama. Susun slide presentasi pitch deck. Submit Pitch Deck.', '2026-02-10 02:32:40.974877+00', '2026-03-26 12:14:35.072579+00', NULL, NULL, NULL),
