	('651b241f-88d0-4121-9139-6f8a2e9bcb3f', 'cd5e0fe1-2792-490f-9b81-8068c505c53c', '188956e3-c9ff-45cc-9c19-81a0e9ce8992', 'Explore MakeCode (Part 2)', 'Pembelajaran platform MakeCode Arcade. Siswa membuat game retro sederhana.', 2002, NULL, NULL, 'Pelajari MakeCode Arcade interface. Buat game simple sprite movement dan tilemap. Submit game link.', '2026-01-29 09:43:55.061761+00', '2026-03-26 12:14:22.312495+00', NULL, NULL, NULL),
	('89434622-12bc-4b31-9a39-bf4651fabb29', 'cd5e0fe1-2792-490f-9b81-8068c505c53c', '99a92139-18e8-47f1-8c7f-395f5fd8ac2d', 'Enterpreneurship Big Project 4 (Part 4)', 'Proyek kewirausahaan besar keempat dengan tema bebas.', 6004, NULL, NULL, 'Kerjakan Big Project 4 Game Dev. Buat game original lengkap dengan GDevelop atau MakeCode. Submit game dan GDD.', '2026-01-29 09:43:55.061761+00', '2026-03-26 12:14:22.778432+00', NULL, NULL, NULL),
