	('19b4bad8-235b-4848-9d69-77be657d1b83', 'a62ca0b4-f3a9-4e49-ad01-899bc32eb54c', '0ccfb49f-7bc5-47a9-8539-db1efb88b114', 'Figma to Prototype', 'Mendesain antarmuka app pribadi siswa. Rancang wireframe dan UI app pilihan siswa themes habit atau journal.', 2001, 'f2f8e08e-03ae-45fd-8db6-6efd8138ba21', '2025-12-20 06:00:00+00', 'Rancang UI/UX aplikasi di Figma. Buat wireframe dan high-fidelity prototype. Submit UI Prototype.', '2026-01-29 09:43:54.911647+00', '2026-03-26 12:14:21.143779+00', NULL, NULL, NULL),
	('75d512e5-5820-4fc3-94ed-3c6fbcc6ddeb', '66a7e089-a7fe-4640-be1d-01394b3665e5', '49e73926-f8ce-46ef-a607-560a2a176c29', 'Latihan Presentasi', '', 11001, NULL, NULL, NULL, '2026-01-29 09:36:11.422452+00', '2026-03-26 14:05:09.091249+00', NULL, NULL, NULL),
