	('a60363d5-48d3-4b84-88c0-bf661d0c2741', '4dc0197a-c2bf-4345-8716-263c5bbb35e1', '39ef23dd-304b-4cd1-887c-479e5400aae4', 'Explore Code.org (Part 1)', 'Pembelajaran logika pemrograman menggunakan Code.org untuk memperkuat fundamental coding skills.', 4001, '6c170e9a-cfc7-41b8-9856-29a7642548af', '2026-01-24 01:30:00+00', 'Pelajari logika pemrograman di Code.org. Complete course modules tentang loops conditionals functions. Submit completion certificates dan reflection.', '2026-01-29 09:36:11.021508+00', '2026-03-26 14:05:06.680342+00', NULL, NULL, NULL),
