	('42949a65-17b9-4214-9b94-a58b8268b38d', '512f14b0-b001-4d39-be3e-2cb78595374e', '[{"id": "qm0eehcp9", "question": "Project apa yang kamu buat saat sesi Big Project ?", "placeholder": "Jelaskan tentang project nya"}, {"id": "d2ob6m3fj", "question": "Bagian paling kamu suka dalam project-mu ?", "placeholder": "Bagian paling seru dalam project kamu"}, {"id": "08hvhv3c4", "question": "Apakah project buatan-mu sudah berjalan dengan baik ?", "placeholder": "Jelaskan apakah project kamu sudah baik atau masih ada bug"}, {"id": "v2kq7kqd4", "question": "Apa yang kamu lakukan saat mengelamai kesulitan ?", "placeholder": "Kesulitan saat pembuatan project"}, {"id": "u43ygxpze", "question": "Jika kamu mempunyai waktu lagi, apa yang ingin di tambahkan dalam project-mu?", "placeholder": "Hal yang ingin di tambahkan jika ada waktu tambahan"}, {"id": "ww1zj16dg", "question": "Apa yang ingin ditambahkan agar project-mu lebih seru ?", "placeholder": "Hal yang bisa membuat project kamu lebih menarik"}, {"id": "rt1ihnxl7", "question": "Apa yang kamu lakukan untuk membantu tim kamu ?", "placeholder": "Yang kamu lakukan untuk tim mu"}, {"id": "09x2jwq62", "question": "Apakah kamu senang berkerja sama dengan tim kamu ?", "placeholder": "Apakah kamu senang berkerja sama dengan tim"}]', '2026-03-26 04:51:20.791437+00', '2026-03-26 04:51:20.791437+00'),
