	('5a005027-2f5c-4c8a-83f0-c58502add252', '9c4c5a7e-ec28-4ca9-8621-c50147997fe7', '[{"id": "4zwglc6p3", "question": "Project apa yang kamu buat saat sesi Big Project ?", "placeholder": "Project yang dibuat saat big project"}, {"id": "abo0prtn8", "question": "Masalah apa yang bisa di selesaikan oleh project kamu ?", "placeholder": "Project kamu bisa menjadi solusi dari sebuah masalah"}, {"id": "j6qyyo99n", "question": "Seberapa efektif solusi yang kamu buat dari project kamu ?", "placeholder": "Seberapa efektif project kamu untuk jadi solusi"}, {"id": "un0p8ps8b", "question": "Apa kelebihan project kamu di banding yang lain ?", "placeholder": "Kelebihan project kamu"}, {"id": "wfgyvw004", "question": "Apa kekurangan yang kamu lihat dalam project kamu ?", "placeholder": "Kekurangan dalam project kamu"}, {"id": "848zlivog", "question": "Apa masalah yang sering kamu temui saat membuat project ?", "placeholder": "Masalah yang sering muncul saat project"}, {"id": "7581tecd6", "question": "Apa yang kamu dan tim lakukan jika menemukan masalah tersebut ?", "placeholder": "Yang dilakukan untuk menyelesaikan masalah"}, {"id": "bw1jesigc", "question": "Keputusan apa yang paling berpengaruh terhadap hasil akhir project ?", "placeholder": "Keputusan paling berpengaruh pada project"}, {"id": "mh29cm3zw", "question": "Jika project ini di kembangkan kembali, apa prioritas utama yang ingin kamu perbaiki ?", "placeholder": "hal yang ingin kamu kembangkan dalam project"}, {"id": "rxnaa9awg", "question": "Bagaimana bisa cara meningkatkan User Experience dan User Interface pada project mu ?", "placeholder": "yang bisa di tingkatkan dai UI dan UX"}, {"id": "rztdbsulr", "question": "Apakah pembagian role dalam tim sudah efektif ?", "placeholder": "Efektifitas pembagian role tim"}, {"id": "b006i4nth", "question": "Apa kelebihan dan kekurangan dalam tim kamu ?", "placeholder": "Kelebihan dan Kelemahan Tim"}, {"id": "ojjmon7nb", "question": "Jika mengulang project, hal berbeda apa yang ingin kamu lakukan dengan tim agar lebih baik ?", "placeholder": "hal berbeda yang dilakukan dengan tim agar lebih baik"}]', '2026-03-26 06:54:15.680711+00', '2026-03-26 06:54:15.680711+00');
