INSERT INTO "public"."evaluation_criteria" ("id", "name", "description", "order_index", "created_at", "updated_at") VALUES
	('70d04118-8ba3-427a-90e9-52bb4d2c19d6', 'Logika Pemrograman', 'memahami dan menyusun alur berpikir sistematis untuk membuat program atau game. Meliputi cara menyusun urutan perintah (sequence), penggunaan kondisi (if-else), pengulangan (loop), serta bagaimana murid merancang alur agar program dapat berjalan dengan benar', 1, '2026-03-12 02:54:29.85616+00', '2026-03-12 02:54:29.85616+00'),
	('dcdedcfc-c8ae-4c20-8cac-40378e06063b', 'Kreativitas', 'menuangkan ide menjadi sebuah project yang unik, menarik, dan memiliki nilai orisinalitas. Kreativitas tidak hanya dari visual, tetapi juga dari konsep game, cerita, fitur, dan cara penyampaian ide.', 2, '2026-03-12 02:54:29.85616+00', '2026-03-12 02:54:29.85616+00'),
	('5c81407b-6c1f-4a08-862b-15720fc6ee73', 'Pemecahan Masalah (Problem Solving)', 'mengidentifikasi masalah, mencari penyebab error, serta menemukan solusi secara mandiri maupun dengan bantuan. Termasuk ketekunan dalam mencoba berbagai cara hingga masalah terselesaikan.', 3, '2026-03-12 02:54:29.85616+00', '2026-03-12 02:54:29.85616+00'),
	('f8e7dcb1-7c8f-42b6-8fa2-a2304beb1896', 'Pemahaman Konsep', 'memahami konsep dasar yang dipelajari, bukan sekadar mengikuti instruksi. Murid diharapkan mengerti “mengapa” dan “bagaimana” suatu fitur atau kode bekerja.', 4, '2026-03-12 02:54:29.85616+00', '2026-03-12 02:54:29.85616+00'),
	('5ae2741c-4c39-4fe4-b720-fcb999dbb8a4', 'Kemampuan Berkolaborasi & Komunikasi', 'bekerja sama dalam tim, berbagi ide, serta menyampaikan pendapat dengan baik. Termasuk kemampuan mendengarkan, menghargai pendapat orang lain, dan berkontribusi dalam project kelompok.', 5, '2026-03-12 02:54:29.85616+00', '2026-03-12 02:54:29.85616+00');
INSERT INTO "public"."block_report_descriptions" ("id", "report_id", "criteria_id", "score", "description", "created_at", "updated_at") VALUES
	('4059e3b8-81c6-4e98-99e7-e83223a55c35', 'fd8ed612-e4a0-4ffa-86ac-5a136baad302', '70d04118-8ba3-427a-90e9-52bb4d2c19d6', 10.00, 'Ananda Benjamin menunjukkan kemampuan logika pemrograman yang luar biasa. Saat mempelajari struktur kontrol dan algoritma dasar, ia dengan cepat memahami cara mengatur alur program dan membuat keputusan yang tepat. Hal ini menunjukkan bahwa ia mampu berpikir kritis dan logis dalam menyelesaikan setiap tantangan yang diberikan.', '2026-03-26 07:29:31.293819+00', '2026-03-26 07:29:31.293819+00'),
	('8e430f34-c820-4359-b498-8ceffe0e6ad5', 'fd8ed612-e4a0-4ffa-86ac-5a136baad302', 'dcdedcfc-c8ae-4c20-8cac-40378e06063b', 10.00, 'Kreativitas Ananda Benjamin sangat mencolok dalam proyek yang dikerjakannya. Ketika mempelajari bagaimana menggabungkan berbagai elemen dalam coding, ia berhasil menciptakan solusi yang unik dan menarik, menunjukkan bahwa ia tidak hanya memahami materi, tetapi juga mampu menerapkannya dengan cara yang inovatif.', '2026-03-26 07:29:31.293819+00', '2026-03-26 07:29:31.293819+00'),
	('c661df44-87e2-4656-a145-eaf4977ca941', 'fd8ed612-e4a0-4ffa-86ac-5a136baad302', '5c81407b-6c1f-4a08-862b-15720fc6ee73', 10.00, 'Kemampuan pemecahan masalah Ananda Benjamin sangat mengesankan. Dalam sesi praktikum yang mengharuskan siswa untuk menganalisis dan menyelesaikan tantangan yang kompleks, ia dapat dengan cepat mengidentifikasi masalah dan menemukan solusi yang efektif, mencerminkan pemahaman mendalam terhadap konsep yang telah dipelajari.', '2026-03-26 07:29:31.293819+00', '2026-03-26 07:29:31.293819+00'),
	('52b0dbc2-deea-4a71-88cb-04aa00b80d5b', 'fd8ed612-e4a0-4ffa-86ac-5a136baad302', 'f8e7dcb1-7c8f-42b6-8fa2-a2304beb1896', 10.00, 'Ananda Benjamin menunjukkan pemahaman konsep yang solid dalam setiap topik yang dibahas. Ia tidak hanya mampu menjelaskan teori di balik coding, tetapi juga dapat mengaitkannya dengan aplikasi praktis, yang menunjukkan bahwa ia benar-benar menginternalisasi materi dan siap untuk tantangan yang lebih besar.', '2026-03-26 07:29:31.293819+00', '2026-03-26 07:29:31.293819+00'),
	('420f0c20-83da-4af5-8711-a3dafb39a5d1', 'fd8ed612-e4a0-4ffa-86ac-5a136baad302', '5ae2741c-4c39-4fe4-b720-fcb999dbb8a4', 10.00, 'Kemampuan Ananda Benjamin dalam berkolaborasi dan berkomunikasi dengan teman-temannya sangat mengesankan. Selama proyek kelompok, ia aktif berpartisipasi dalam diskusi dan mampu menyampaikan ide-ide dengan jelas, menciptakan suasana kerja yang produktif dan harmonis di antara rekan-rekannya.', '2026-03-26 07:29:31.293819+00', '2026-03-26 07:29:31.293819+00'),
	('642ea318-2bb9-495e-8c37-ea8980ffe512', '2e388f40-e9a5-4e49-aa2c-eccafa94f107', '70d04118-8ba3-427a-90e9-52bb4d2c19d6', 10.00, 'Ananda Al Fatih Taslim menunjukkan pemahaman yang luar biasa dalam logika pemrograman. Saat mempelajari struktur kontrol dan algoritma, Ananda mampu menerapkan konsep-konsep tersebut dengan tepat dalam proyek-proyek yang dikerjakan, menunjukkan kemampuan berpikir analitis yang sangat baik.', '2026-03-26 07:29:17.297322+00', '2026-03-26 07:30:23.066139+00'),
	('0cfa4a4b-4afb-4e93-8697-d432354f1409', '2e388f40-e9a5-4e49-aa2c-eccafa94f107', 'dcdedcfc-c8ae-4c20-8cac-40378e06063b', 10.00, 'Dalam aspek kreativitas, Ananda Al Fatih Taslim sangat menonjol. Ketika bereksperimen dengan berbagai ide dalam proyek coding, Ananda tidak hanya mengandalkan teknik yang telah diajarkan, tetapi juga berani mengembangkan ide-ide baru yang memberikan nilai tambah pada hasil akhir.', '2026-03-26 07:29:17.297322+00', '2026-03-26 07:30:23.066139+00'),
	('62881058-8758-438b-b7d0-fa804a67a9f2', '2e388f40-e9a5-4e49-aa2c-eccafa94f107', '5c81407b-6c1f-4a08-862b-15720fc6ee73', 10.00, 'Ananda Al Fatih Taslim menunjukkan kemampuan pemecahan masalah yang sangat baik. Dalam setiap tantangan yang dihadapi saat belajar materi pemrograman, Ananda mampu menganalisis masalah dengan cermat dan menemukan solusi yang efektif, mencerminkan ketekunan dan keterampilan berpikir kritis yang sangat baik.', '2026-03-26 07:29:17.297322+00', '2026-03-26 07:30:23.066139+00'),
	('bbbdfe50-fa64-4bf5-9dc6-55817eb22e21', '2e388f40-e9a5-4e49-aa2c-eccafa94f107', 'f8e7dcb1-7c8f-42b6-8fa2-a2304beb1896', 10.00, 'Pemahaman konsep yang dimiliki Ananda Al Fatih Taslim sangat mengesankan. Saat mempelajari berbagai konsep dasar pemrograman, Ananda dengan cepat menangkap inti dari setiap materi, mampu menjelaskan kembali dengan jelas kepada teman-temannya, dan menunjukkan penguasaan yang solid atas isi materi.', '2026-03-26 07:29:17.297322+00', '2026-03-26 07:30:23.066139+00'),
	('3eb6b59d-1099-4bf0-a849-3deece9861fc', '2e388f40-e9a5-4e49-aa2c-eccafa94f107', '5ae2741c-4c39-4fe4-b720-fcb999dbb8a4', 10.00, 'Ananda Al Fatih Taslim menunjukkan kemampuan berkolaborasi dan komunikasi yang sangat baik dalam kelompok. Ketika bekerja dalam tim, Ananda tidak hanya aktif berbagi ide, tetapi juga mendengarkan masukan dari anggota lainnya, menciptakan lingkungan belajar yang positif dan produktif.', '2026-03-26 07:29:17.297322+00', '2026-03-26 07:30:23.066139+00');
