INSERT INTO "public"."n8n_chat_histories" ("id", "session_id", "message") VALUES
	(4355, '6281212022628', '{"type": "human", "content": "Kelas 7 berapa bundling nya", "additional_kwargs": {}, "response_metadata": {}}'),
	(4356, '6281212022628', '{"type": "ai", "content": "Untuk kelas 7 SMP sampai 12 SMA, harga bundling 3 kelas adalah Rp450.000, dengan diskon Rp75.000 dari harga total satuan Rp525.000 (Rp175.000 per kelas).\n\nApakah Ayah/Bunda ingin saya jelaskan pilihan materi atau jadwal untuk bundling kelas 7? 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(3, '628128186913', '{"type": "human", "content": "terima kasih infonya.", "additional_kwargs": {}, "response_metadata": {}}'),
	(4, '628128186913', '{"type": "ai", "content": "Sama-sama Ayah/Bunda! 😊 Kalau nanti Ayah/Bunda ada pertanyaan lain atau ingin saya bantu daftar, jangan ragu ya. Saya siap membantu kapan saja. Semoga putra/putri Ayah/Bunda senang dan semangat belajar coding di Clevio! 🙏👍", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(4357, '6281212022628', '{"type": "human", "content": "450 udah diskon apa belu?", "additional_kwargs": {}, "response_metadata": {}}'),
	(4358, '6281212022628', '{"type": "ai", "content": "Rp450.000 itu sebelum diskon Ayah/Bunda, setelah diskon bundling harganya jadi Rp375.000, hemat Rp75.000 dari total harga satuan Rp525.000.\n\nAyah/Bunda tertarik ambil bundling kelas 7 dengan harga spesial ini? Saya bisa bantu pilih materinya juga 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(4555, '6287856251122', '{"type": "human", "content": "halo mau info kelas 4 dong kelas ramadhan", "additional_kwargs": {}, "response_metadata": {}}'),
	(4556, '6287856251122', '{"type": "ai", "content": "Halo Ayah/Bunda! Boleh saya tahu putra/putrinya kelas 4 ya? Anak Ayah/Bunda tertarik ke materi seperti apa untuk Ramadhan Class? Supaya saya bisa kasih info kelas dan jadwal yang sesuai 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(4557, '6287856251122', '{"type": "human", "content": "hah? ada materi apa aja?", "additional_kwargs": {}, "response_metadata": {}}'),
	(4558, '6287856251122', '{"type": "ai", "content": "Untuk kelas 4, ada materi seru seperti:\n\n- Social Media Content dengan tema *Fact vs Hoax Campaign* untuk melatih anak berpikir kritis tentang informasi.  \n- Video Explainer tentang *The Science of Fasting* yang memudahkan anak memahami sains tubuh saat puasa.  \n- Personal Blog/Profile bertema *Local Hero Profile* mengenalkan cerita inspiratif kenyataan sekitar.  \n- Interactive Quiz Game dengan tema *Cultural Diversity Quiz* yang asik sekaligus edukatif.  \n- Environmental Campaign *Go Green Movement* untuk menanamkan kesadaran lingkungan.  \n- Music/Podcast Cover yang membantu skill ekspresi artistik lewat identitas visual.  \n- Tutorial Video *Life Skills Academy* melatih komunikasi lewat video praktis.\n\nAyah/Bunda tertarik ke materi yang mana? Saya bisa bantu jelaskan lebih detail dan informasikan jadwalnya! 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(4559, '6287856251122', '{"type": "human", "content": "coba kasih jadwalnya juga dong", "additional_kwargs": {}, "response_metadata": {}}'),
	(4560, '6287856251122', '{"type": "ai", "content": "Untuk kelas 4 SD di Ramadhan Class, jadwal dan temanya sebagai berikut:\n\n- Minggu 1: Kamis, 26 Februari 2026, 15.30 - 17.30, tema *Canva - Social Media Content*  \n- Minggu 2: Senin, 2 Maret 2026, 15.30 - 17.30, *Personal Blog/Profile*; Selasa, 3 Maret 2026, 15.30 - 17.30, *Interactive Quiz Game*  \n- Minggu 3: Kamis, 12 Maret 2026, 15.30 - 17.30, *Social Media Content*; Jumat, 13 Maret 2026, 15.30 - 17.30, *Personal Blog/Profile*; Sabtu, 14 Maret 2026, 15.30 - 17.30, *Tutorial Video*\n\nAyah/Bunda tertarik ikut minggu berapa dan topik yang mana? Saya bisa bantu proses pendaftaran ya 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(4705, '196585719857358', '{"type": "human", "content": "Selamat pagi", "additional_kwargs": {}, "response_metadata": {}}'),
	(4706, '196585719857358', '{"type": "ai", "content": "Selamat pagi Ayah/Bunda! Ada yang bisa saya bantu hari ini terkait Ramadhan Class atau proses refund sebelumnya? 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(15, '6281329325316', '{"type": "human", "content": "Halo! Bisakah saya mendapatkan info selengkapnya tentang ini?", "additional_kwargs": {}, "response_metadata": {}}'),
	(16, '6281329325316', '{"type": "ai", "content": "Halo Ayah/Bunda! 👋 Terima kasih sudah menghubungi Clevio Innovator Camp.\n\nBoleh tahu putra/putri Ayah/Bunda saat ini kelas berapa? Dengan begitu saya bisa jelaskan program coding Holiday Class yang paling sesuai dan lengkap untuk kebutuhan mereka ya. 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(17, '6281288898393', '{"type": "human", "content": "*[Auto-Reply Message 🤖]*\n\nHi there! 👋 Denny here.\nMay I know your purpose, how you got this number, and what it’s regarding? 😊\n\nIf it’s about Toys Kingdom events, feel free to send your proposal to 📧 *events@toyskingdom.co.id*\n\nThanks a lot! 🙏\n\n🔕 _Note: Any messages that appear to be spam, phishing, or scam-related will be reported immediately._", "additional_kwargs": {}, "response_metadata": {}}'),
