	(1104, '6281296896811', '{"type": "ai", "content": "Halo Ayah/Bunda! 👋 Saya CS AI dari Clevio Innovator Camp. Senang bisa membantu Ayah/Bunda hari ini. Ada yang ingin ditanyakan tentang program coding untuk putra/putri Ayah/Bunda?", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(1105, '6287780786297', '{"type": "human", "content": "Dear Parent,\n\nThank you for contacting us.\n\nYour messages are important to us, and we are happy to reply soon, during our office hours: Monday - Friday: 07.30 - 15.30.\n\nIn the meantime, we hope your afternoon will be blessed and enjoyable with your family ❤️.\n\nGod cares for you and so do we 😊 Thank you and God bless you 🙏", "additional_kwargs": {}, "response_metadata": {}}'),
	(1106, '6287780786297', '{"type": "ai", "content": "Halo Ayah/Bunda! 👋 Saya CS AI dari Clevio Innovator Camp. Senang bisa membantu Ayah/Bunda hari ini. Ada yang ingin ditanyakan tentang program coding untuk putra/putri Ayah/Bunda?", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
	(1107, '62811687400', '{"type": "human", "content": "Assalamu''alaikum Ayah/Bunda..\nTerima kasih telah menghubungi Sekolah Islam Al-Azhar Cairo Banda Aceh. Silakan beri tahu apa yang bisa kami bantu 🙏☺️", "additional_kwargs": {}, "response_metadata": {}}'),
	(1108, '62811687400', '{"type": "ai", "content": "Wa''alaikumussalam Ayah/Bunda! 👋\n\nTerima kasih sudah menghubungi, saya dari CS AI Clevio Innovator Camp. Senang bisa membantu Ayah/Bunda hari ini.\n\nBoleh tahu putra/putri Ayah/Bunda saat ini kelas berapa? Agar saya bisa informasikan program coding Holiday Class yang cocok dan bermanfaat untuk liburan mereka ya 😊", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}'),
